using System;using System.IO;using System.Text;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Globalization;using System.Reflection;using System.Windows.Forms;using System.Web.Script.Serialization;
namespace GearLab {
 public interface IUserDialogs {
  string Save(IWin32Window owner,string extension,string suggested);string Open(IWin32Window owner);DialogResult Unsaved(IWin32Window owner);void Info(IWin32Window owner,string text,string title);void Help(IWin32Window owner);
 }
 public sealed class UserDialogs:IUserDialogs {
  public string Save(IWin32Window owner,string extension,string suggested){using(var d=new SaveFileDialog{Filter=extension=="gear.json"?"Проект редуктора (*.gear.json)|*.gear.json":extension.ToUpper()+" (*."+extension+")|*."+extension,DefaultExt=extension,AddExtension=true,OverwritePrompt=true,RestoreDirectory=true,InitialDirectory=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),FileName=suggested})return d.ShowDialog(owner)==DialogResult.OK?d.FileName:null;}
  public string Open(IWin32Window owner){string examples=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Примеры");using(var d=new OpenFileDialog{Filter="Проект редуктора (*.gear.json;*.json)|*.gear.json;*.json",CheckFileExists=true,RestoreDirectory=true,InitialDirectory=Directory.Exists(examples)?examples:Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments)})return d.ShowDialog(owner)==DialogResult.OK?d.FileName:null;}
  public DialogResult Unsaved(IWin32Window owner){return MessageBox.Show(owner,"Сохранить изменения текущего проекта?\n«Нет» продолжит без сохранения.","Несохранённый проект",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);}
  public void Info(IWin32Window owner,string text,string title){MessageBox.Show(owner,text,title,MessageBoxButtons.OK,MessageBoxIcon.Information);}
  public void Help(IWin32Window owner){using(var f=new Form{Text="Gear Lab — справка",Size=new Size(780,650),MinimumSize=new Size(550,400),StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false}){
   var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,WordWrap=true,Font=new Font("Segoe UI",11),BackColor=Color.White,Text=ReleaseSupport.HelpText};f.Controls.Add(box);f.ShowDialog(owner);}}
 }
 public static class ReleaseSupport {
  public const string Version="1.5.0";
  public const string HelpText="НОВОЕ В 1.5: перемещение отдельных деталей в 3D. Справа включите «Перетаскивать детали мышью», выберите деталь в сцене или дереве. Можно двигать в плоскости экрана либо по X/Y/Z и задавать сдвиги в миллиметрах. Если ось направлена точно в камеру, смените вид или используйте числовое поле. Esc отменяет текущее перетаскивание. «Вернуть деталь» и «Вернуть все» восстанавливают положение. Сдвиги сохраняются при анимации, скрытии и смене вида, но сбрасываются при изменении геометрии/открытии проекта. Это просмотр: STEP/STL и сохранённый проект содержат рассчитанную сборку.\r\n\r\nНОВОЕ В 1.4: компоновка «Micro · квадратное основание NEMA 17» и набор «Micro 20:1 · NEMA 17 · 42 мм». Два диска, круглый корпус на двух опорах, квадратное основание и утопленные винты. Это собственная параметрическая модель по открытому референсу Sweep Dynamics. Посадки, материал, крепёж и характеристики нужно проверить; силовые показатели оригинала не переносятся. В папке Micro — проекты, полный STEP и пять деталей для печати.\r\n\r\nНОВОЕ В 1.3: кнопка «Для печати…» открывает выбор корпуса, крышек, шестерён и других печатных заготовок. Можно сохранить STEP либо ZIP с отдельными STL (мм, Z=0) и списком деталей. Мотор, подшипники и крепёж исключены. Слева в составе экспорта есть режим «Только детали для печати» для STEP/SVG/DXF/CSV. В циклоидальном режиме флажок «Зацепы кольца — часть корпуса» объединяет зацепы со стенкой; ширина связки 0 означает авто. Старые проекты сохраняют прежние отдельные ролики. Планетарное зубчатое кольцо уже объединено с корпусом. Печатный контакт скользящий: материал, износ, зазоры и прочность нужно проверить.\r\n\r\nGEAR LAB 1.3 — КАЛЬКУЛЯТОР РЕДУКТОРОВ\r\n\r\n1. Выберите тип передачи и размерный набор либо задайте свои размеры.\r\n2. Задайте передаточное число и общий габарит в плоскости. 0 мм снимает ограничение. Автоподбор изменяет геометрию, а ручной режим сохраняет введённый модуль/межосевое.\r\n3. Для планетарной передачи доступен автоматический выбор 1–3 ступеней. Например, 60:1 с тремя сателлитами рассчитывается в несколько ступеней. Ступени расположены вдоль общей оси; отношения перемножаются. Список справа переключает ступень; осевой вид показывает пакет.\r\n4. «Рассчитать» применяет поля. Точка и запятая допустимы. Красные поля и сообщения указывают причину ошибки. Геометрически невозможные варианты не экспортируются в SVG/DXF. CSV черновика содержит ошибки.\r\n5. «Запустить» / «Пауза» управляют движением. Скорость входа задаётся внизу боковой панели. «Вписать» восстанавливает масштаб. Колесо над чертежом меняет масштаб, над параметрами прокручивает панель.\r\n6. Два циклоидальных диска — одна ступень с эксцентриками 180°. Каждый профиль экспортируется с собственной фазой отверстий.\r\n7. Подшипники моделируются в идеальном качении. Внешние размеры 608/625 — шаблоны; число и диаметр шариков условные. Нагрузки и ресурс не рассчитываются.\r\n8. Меню «Проект» сохраняет и открывает .gear.json, сбрасывает текущий тип и предлагает сохранить изменения. Ctrl+S — сохранить, Ctrl+O — открыть, F1 — справка.\r\n9. Меню «Экспорт» сохраняет CSV, SVG и DXF. Для многоступенчатого планетарного узла экспортируются все ступени, разложенные рядом и обозначенные слоями.\r\n\r\nОГРАНИЧЕНИЯ\r\nЭто расчёт геометрии и кинематики. Нужны проверки прочности, материалов, посадок, люфта, технологии зубьев, опор и полного осевого CAD перед изготовлением. Геометрический подбор не определяет допустимый момент.\r\n\r\nПрограмма переносная. Копируйте всю папку релиза; настройки и проекты не требуют исходного компьютера. Windows 10/11, .NET Framework 4.8. Интернет для работы не нужен. Полная инструкция и примеры находятся рядом с GearLab.exe.\r\n\r\nПОЛНАЯ 3D-СБОРКА\r\nКнопка STEP сохраняет всю 3D-сборку с корпусом, крышками, валами, опорами и крепежом. Единицы STEP — миллиметры; откройте файл как 3D-модель, а не через «Вставить SVG». Состав SVG/DXF/CSV выбирается слева: все детали либо только рабочие профили. Виды «Полная 3D сборка» и «Разнесённая 3D сборка» позволяют повернуть модель перетаскиванием. Анимация доступна в 2D и 3D. Кнопка «Запустить» включает движение, «Пауза» останавливает. ЛКМ вращает камеру, СКМ или Shift+ЛКМ сдвигает, колесо масштабирует к курсору, F / Home вписывает модель. Справа: флажки деталей, поиск, изоляция, виды камеры и сечение по XY/XZ/YZ с ползунком и сменой стороны. Скрытие и сечение не меняют экспорт STEP; состав задаёт левый список (при режиме печати — только печатные детали). 3D-опоры показаны габаритными кольцами; шарики моделируются в отдельном 2D-виде подшипника. Параметры корпуса/крышек/опор находятся под флажком «Параметры корпуса и 3D-сборки». Полный размер с мотором показан отдельно: монтажный пояс и реальные опоры увеличивают размер. SVG теперь использует 96 dpi; для проверки в комплекте есть квадрат 10 мм.";
  public static void WriteText(string path,string text,Encoding encoding){string full=Path.GetFullPath(path),dir=Path.GetDirectoryName(full);if(!Directory.Exists(dir))throw new IOException("Папка назначения не существует.");string temp=Path.Combine(dir,".gearlab-"+Guid.NewGuid().ToString("N")+".tmp");try{File.WriteAllText(temp,text,encoding);if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static string Serialize(Parameters p){var fields=new SortedDictionary<string,object>(StringComparer.Ordinal);foreach(var prop in typeof(Parameters).GetProperties())fields[prop.Name]=prop.GetValue(p,null);return new JavaScriptSerializer().Serialize(fields);}
  public static Parameters Parse(string text){
   if(string.IsNullOrWhiteSpace(text)||text.Length>131072)throw new Exception("Пустой или слишком большой файл проекта (максимум 128 КБ). Проект не изменён.");
   var json=new JavaScriptSerializer{MaxJsonLength=131072,RecursionLimit=16};var raw=json.DeserializeObject(text) as Dictionary<string,object>;if(raw==null)throw new Exception("Проект должен быть объектом JSON.");
   foreach(var item in raw){var property=typeof(Parameters).GetProperty(item.Key);if(property==null)throw new Exception("Неизвестное поле проекта: "+item.Key+". Проверьте версию программы.");object value=item.Value;if(property.PropertyType==typeof(bool)){if(!(value is bool))throw new Exception("Поле "+item.Key+" должно быть true/false.");}else{if(value==null||value is bool||value is string||value is Array||value is Dictionary<string,object>)throw new Exception("Поле "+item.Key+" должно содержать число.");double number=Convert.ToDouble(value,CultureInfo.InvariantCulture);if(double.IsNaN(number)||double.IsInfinity(number)||property.PropertyType==typeof(int)&&number!=Math.Truncate(number))throw new Exception("Некорректное число: "+item.Key);}}
   var p=json.Deserialize<Parameters>(text);if(p.CycloidLayout<0||p.CycloidLayout>1||p.Kind<0||p.Kind>3||p.MotorPreset<0||p.MotorPreset>=Engine.PresetNames.Length||p.PlanetStages<0||p.PlanetStages>3||p.FormatVersion!=1||p.ExportScope<0||p.ExportScope>2)throw new Exception("Неподдерживаемая версия, тип или набор параметров проекта.");return p;
  }
  public static void Export(Result result,string type,string path){if(type=="csv"&&!result.Valid){Files.Csv(result,path);return;}var model=result.Model??CadBuilder.Build(result);if(result.P.ExportScope==2)model=PrintExport.Select(model,null);if(type=="step"){StepExport.Write(model,path);return;}if(result.P.ExportScope!=1){FullDrawingExport.Write(model,type,path);return;}if(type=="csv")Files.Csv(result,path);else if(type=="svg")Files.Svg(result,path);else if(type=="dxf")Files.Dxf(result,path);else throw new Exception("Неизвестный формат экспорта.");}
  public static void Report(Exception ex){string path="";try{path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"GearLab","logs");Directory.CreateDirectory(path);path=Path.Combine(path,"error-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".txt");File.WriteAllText(path,"Gear Lab "+Version+Environment.NewLine+(ex==null?"Unknown error":ex.ToString()),Encoding.UTF8);}catch{path="Не удалось записать журнал.";}MessageBox.Show("Не удалось выполнить действие. Сохраните проект под другим именем, если программа продолжает работу.\nЖурнал ошибки: "+path,"Gear Lab — ошибка",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 }
}
